begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
-- Historical stage-5 compatibility suite; stage-6 rules have their own tests.
update private.engine_health set last_successful_tick_at=clock_timestamp() where id;
create temp table match_test_results(line text);
create temp table match_test_data(name text primary key,value jsonb);
grant all on match_test_results,match_test_data to authenticated,anon;
grant usage on schema extensions to authenticated,anon;
-- Calls are separate statements: the limiter returns false instead of rolling back its counter.
select public.match_join_admission(repeat('e',64)) from generate_series(1,9);
set local role anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update public.matches set engine_stage=5 where id=(select (value->>'matchId')::uuid from match_test_data where name='created');
set local role authenticated;
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('realtime.topic','match:'||(select (value->>'matchId')::uuid from match_test_data where name='created')::text,true);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update private.command_receipts set ciphertext_expires_at=created_at+interval '1 microsecond' where user_id='f3000000-0000-4000-8000-000000000001' and command_name='create_match';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.match_command('ready',(select (value->>'matchId')::uuid from match_test_data where name='created'),'a3000000-0000-4000-8000-000000000001'::uuid,true,null,null,null,null);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.match_command('ready',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),true,null,null,null,null);
reset role;
update public.match_rounds set starts_at=now()-interval '1 second',ends_at=now()+interval '44 seconds' where id=(select (value#>>'{round,id}')::uuid from match_test_data where name='countdown');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.match_command('sync',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),null,null,null,null,null);
select public.match_command('answer',(select (value->>'matchId')::uuid from match_test_data where name='created'),'a3000000-0000-4000-8000-000000000001'::uuid,null,(select (value#>>'{round,id}')::uuid from match_test_data where name='countdown'),1,null,null);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.match_command('answer',(select (value->>'matchId')::uuid from match_test_data where name='created'),'a3000000-0000-4000-8000-000000000001'::uuid,null,(select (value#>>'{round,id}')::uuid from match_test_data where name='countdown'),4,null,null);
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
update match_test_data set value=public.match_command('create',null,gen_random_uuid(),null,null,null,repeat('b',64),encode(convert_to('opaque-fixture','UTF8'),'base64')) where name='created';
reset role;
update public.matches set engine_stage=5 where id=(select (value->>'matchId')::uuid from match_test_data where name='created');
set local role authenticated;
select public.match_command('invite',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),null,null,null,repeat('c',64),encode(convert_to('opaque-fixture','UTF8'),'base64'));
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select public.match_command('join',null,gen_random_uuid(),null,null,null,repeat('c',64),null);
select public.match_command('ready',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),true,null,null,null,null);
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.match_command('ready',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),true,null,null,null,null);
update match_test_data set value=public.match_command('get',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),null,null,null,null,null) where name='countdown';
select public.match_command('leave',(select (value->>'matchId')::uuid from match_test_data where name='created'),gen_random_uuid(),null,null,null,null,null);
reset role;
update public.match_rounds set starts_at=now()-interval '1 second',ends_at=now()+interval '44 seconds',resolved_at=now()-interval '2 seconds' where id=(select (value#>>'{round,id}')::uuid from match_test_data where name='countdown');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f3000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
reset role;
select line from match_test_results;
rollback;
