insert into match_test_results values(throws_ok('select public.match_command(''answer'',(select (value->>''matchId'')::uuid from match_test_data where name=''created''),''a3000000-0000-4000-8000-000000000001''::uuid,null,(select (value#>>''{round,id}'')::uuid from match_test_data where name=''countdown''),3,null,null)','P0001','IDEMPOTENCY_CONFLICT','answer key different line conflicts after finish'));
insert into match_test_results values(is((select count(*) from private.answers where match_id=(select (value->>'matchId')::uuid from match_test_data where name='created') and is_correct),1::bigint,'one correct answer evidence'));
insert into match_test_results values(ok((select winning_points between 100 and 150 from public.match_rounds where id=(select (value#>>'{round,id}')::uuid from match_test_data where name='countdown')),'DB score follows fixed range'));
insert into match_test_results values(ok((select awarded_points=100+floor(50.0*(45000-elapsed_ms)/45000)::integer from private.answers where match_id=(select (value->>'matchId')::uuid from match_test_data where name='created') and is_correct),'persisted score matches the exact fixed speed formula'));
insert into match_test_results values(ok((select a.elapsed_ms=floor(extract(epoch from(a.accepted_at-r.starts_at))*1000)::integer and a.elapsed_ms>=0 and a.elapsed_ms<45000 from private.answers a join public.match_rounds r on r.id=a.round_id where a.match_id=(select (value->>'matchId')::uuid from match_test_data where name='created') and a.is_correct),'elapsed time comes from the accepted DB clock and stays inside deadline'));
insert into match_test_results values(is((select count(*) from public.match_players where match_id=(select (value->>'matchId')::uuid from match_test_data where name='created') and is_active),0::bigint,'preview frees active seats'));
insert into match_test_results values(is((select count(*) from public.match_rounds where match_id=(select (value->>'matchId')::uuid from match_test_data where name='created') and round_number>1 and end_reason='match_ended'),2::bigint,'unplayed future rounds closed without snapshots'));
