insert into match_test_results values(is((select sum(matches_played) from public.profiles where id in('f3000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000003')),0::bigint,'preview does not write permanent match statistics'));
